            "anyOf": [
              {
                "type": "string",
                "description": "Relative time range, e.g. '24h', '7d', '30d'. Mutually exclusive with start/end."
              },
              {
                "type": "null"
              }
            ]
          },
          "start": {
            "default": null,
            "anyOf": [
              {
                "type": "string",
                "description": "Absolute start (ISO 8601). Must be paired with end."
              },
              {
                "type": "null"
              }
            ]
          },
          "end": {
