                "type": "string",
                "description": "Bucket size, e.g. '1h', '1d'. Omit to let Sentry pick for the range."
              },
              {
                "type": "null"
              }
            ]
          },
          "outcome": {
            "default": null,
            "anyOf": [
              {
                "type": "string",
                "enum": [
